s("push_timeRow", "Every evening at {time}", "On the notification explainer: when the daily nudge comes; {time} e.g. '8:00 PM'.", "ప్రతి సాయంత్రం {time}కి", "Prati saayantram {time} ki", STR("time"), hi="हर शाम {time} पर", hl="Har shaam {time} par")
s("push_changeTime", "Change time", "Opens the time picker on the explainer.", "సమయం మార్చండి", "Time maarchandi", hi="समय बदलें", hl="Time badlein")
s("push_discreet", "Keep them discreet", "Checkbox on the explainer: discreet mode (PRD 12 rule 4, a one-tap choice on the permission screen). The line under it quotes the discreet text.", "గోప్యంగా ఉంచండి", "Discreet ga unchandi", hi="इन्हें गोपनीय रखें", hl="Inhe discreet rakhein")

# ==== F14 Milestone B (contracts/api/v1-notifications.md §6–§10) =============
# The rest of the PRD 12 catalogue: gestures received, Lantern Hour, the
# opt-in wind-down reminder (REQ-NTF-04), habit nudges, welcome back, and the
# crisis follow-up card (in-app only, never a push). `notif_*` keys are
# copy-linted (REQ-NTF-01 + the "calm, not treatment" claim list).

# ---- in-app notices for pushes that arrive while Aura is open ---------------
s("notif_gesturesBanner", "People in your room sent you warmth.", "In-app notice when the 'gestures received' push arrives while the app is open. Never a pseudonym, count of gestures, theme or mood.", "మీ రూమ్‌లో కొందరు మీకు ఆత్మీయత పంపారు.", "Mee room lo kondaru meeku warmth pampaaru.", hi="आपके रूम के लोगों ने आपको अपनापन भेजा।", hl="Aapke room ke logon ne aapko warmth bheji.")
s("notif_gesturesAction", "Open room", "Action on the gestures notice: opens that room.", "రూమ్ తెరవండి", "Room open cheyandi", hi="रूम में जाएँ", hl="Room mein jaayein")
s("notif_lanternBanner", "Lantern Hour is on. Others are here tonight.", "In-app notice when the Lantern Hour push arrives while the app is open (PRD catalogue line).", "Lantern Hour మొదలైంది. ఈ రాత్రి ఇంకా కొందరు ఇక్కడే ఉన్నారు.", "Lantern Hour modalaindi. Ee raatri inka kondaru ikkade unnaru.", hi="Lantern Hour शुरू हो गया है। आज रात और लोग भी यहाँ हैं।", hl="Lantern Hour shuru ho gaya hai. Aaj raat aur log bhi yahan hain.")
s("notif_lanternAction", "See rooms", "Action on the Lantern Hour notice: opens Rooms.", "రూమ్‌లు చూడండి", "Rooms chudandi", hi="रूम देखें", hl="Rooms dekhein")
s("notif_windDownBanner", "A few quiet minutes before sleep, whenever you want them.", "In-app notice for the wind-down reminder (PRD line). Never promises better sleep (REQ-NTF-04).", "పడుకునే ముందు కొంచెం నిశ్శబ్ద సమయం? Aura ఇక్కడే ఉంది.", "Padukune mundu konchem quiet time? Aura ikkade undi.", hi="सोने से पहले सुकून के कुछ पल, जब भी मन हो।", hl="Sone se pehle sukoon ke kuch pal, jab bhi mann ho.")
s("notif_windDownAction", "Open Sounds", "Action on the wind-down notice: opens Sanctuary › Sounds (nothing plays until a tap).", "శబ్దాలు తెరవండి", "Sounds open cheyandi", hi="आवाज़ें देखें", hl="Sounds kholein")
s("notif_habitBanner", "A small habit or two, whenever you're ready.", "In-app notice for a habit nudge. Never a habit's name.", "ఒక చిన్న అలవాటు, మీకు వీలైనప్పుడు.", "Oka chinna habit, meeku veelainappudu.", hi="एक-दो छोटी आदतें, जब भी आप तैयार हों।", hl="Ek-do chhoti habits, jab bhi aap taiyaar hon.")
s("notif_habitAction", "See habits", "Action on the habit nudge notice: opens Home.", "అలవాట్లు చూడండి", "Habits chudandi", hi="आदतें देखें", hl="Habits dekhein")
s("notif_crisisFollowUp", "Just checking in. However today feels, help is one tap away.", "Crisis follow-up (PRD 12): an in-app card on the next open 12–72 h after the support sheet showed. Never a push, never mentions distress or what happened.", "ఊరికే అడుగుతున్నాం, ఈ రోజు ఎలా ఉంది? సహాయం ఒక్క ట్యాప్ దూరంలో ఉంది.", "Oorike adugutunnam, ee roju ela undi? Help oka tap dooram lo undi.", hi="बस हालचाल पूछ रहे हैं। आज जैसा भी लग रहा हो, मदद बस एक टैप दूर है।", hl="Bas haal-chaal pooch rahe hain. Aaj jaisa bhi lag raha ho, madad bas ek tap door hai.")
s("notif_crisisFollowUpDismiss", "Close", "Closes the follow-up card (it doesn't come back for this time).", "మూసివేయండి", "Close cheyandi", hi="बंद करें", hl="Band karein")
edit("notif_channelRemindersDescription", en="Your check-in, wind-down and habit reminders.", te="మీ చెక్-ఇన్, నిద్రకు ముందు, అలవాట్ల రిమైండర్లు.", tl="Mee check-in, wind-down, habit reminders.", hi="आपके चेक-इन, सोने से पहले के सुकून और आदत के रिमाइंडर।", hl="Aapke check-in, wind-down aur habit reminders.")
edit("notif_channelRoomsDescription", en="Lantern Hour, warmth from your room, and rooms you asked about.", te="Lantern Hour, మీ రూమ్ నుండి ఆత్మీయత, మీరు అడిగిన రూమ్‌లు.", tl="Lantern Hour, mee room nundi warmth, meeru adigina rooms.", hi="Lantern Hour, आपके रूम से अपनापन, और वे रूम जिनके बारे में आपने पूछा।", hl="Lantern Hour, aapke room se warmth, aur woh rooms jinke baare mein aapne poochha.")

# ---- Settings › Notifications (per-type toggles, PRD 12 rule 8) -------------
s("set_notifGestures", "Warmth from your room", "Switch: the 'gestures received' push (batched).", "మీ రూమ్ నుండి ఆత్మీయత", "Mee room nundi warmth", hi="आपके रूम से अपनापन", hl="Aapke room se warmth")
s("set_notifGesturesNote", "When people in your room send you a gesture. One a day at most.", "Under the gestures switch.", "మీ రూమ్‌లో ఎవరైనా మీకు గెస్చర్ పంపినప్పుడు. రోజుకు ఒక్కటి మించదు.", "Mee room lo evaraina meeku gesture pampinappudu. Rojuki okkati minchadu.", hi="जब आपके रूम के लोग आपको कोई भाव भेजें। दिन में ज़्यादा से ज़्यादा एक।", hl="Jab aapke room ke log aapko koi gesture bhejein. Din mein zyada se zyada ek.")
s("set_notifLantern", "Lantern Hour", "Switch: the opt-in Lantern Hour push.", "Lantern Hour", "Lantern Hour", hi="Lantern Hour", hl="Lantern Hour")
s("set_notifLanternNote", "When Lantern Hour starts in your evening. Not if you've already been in a room that day.", "Under the Lantern Hour switch (region clock, around 9 pm).", "మీ సాయంత్రం Lantern Hour మొదలైనప్పుడు. ఆ రోజు మీరు ఇప్పటికే రూమ్‌లో ఉంటే రాదు.", "Mee saayantram Lantern Hour modalainappudu. Aa roju meeru ippatike room lo unte raadu.", hi="जब आपकी शाम में Lantern Hour शुरू हो। अगर उस दिन कोई रूम पहले ही देखा जा चुका है, तो नहीं।", hl="Jab aapki shaam mein Lantern Hour shuru ho. Agar us din koi room pehle hi dekha ja chuka hai, to nahi.")
s("set_notifWindDown", "Wind-down reminder", "Switch: the opt-in wind-down reminder (REQ-NTF-04).", "నిద్రకు ముందు రిమైండర్", "Wind-down reminder", hi="सोने से पहले के सुकून का रिमाइंडर", hl="Wind-down reminder")
s("set_notifWindDownNote", "A few quiet minutes at {time}. Not sent once you've used Sanctuary that evening.", "Under the wind-down switch when on; {time} e.g. '10:30 PM'. No sleep promise.", "{time}కి కొంచెం నిశ్శబ్ద సమయం. ఆ సాయంత్రం మీరు Sanctuary వాడితే రాదు.", "{time} ki konchem quiet time. Aa saayantram meeru Sanctuary vaadite raadu.", STR("time"), hi="{time} पर सुकून के कुछ मिनट। अगर उस शाम सुकून टैब इस्तेमाल हो चुका है, तो नहीं भेजा जाता।", hl="{time} par sukoon ke kuch minute. Agar us shaam Sanctuary use ho chuka hai, to nahi bheja jata.")
s("set_notifWindDownOffNote", "Off. Pick a time for a quiet nudge before sleep.", "Under the wind-down switch when off.", "ఆఫ్‌లో ఉంది. నిద్రకు ముందు ఒక నిశ్శబ్ద గుర్తు కోసం సమయం ఎంచుకోండి.", "Off lo undi. Padukune mundu oka quiet nudge kosam time select cheyandi.", hi="बंद है। सोने से पहले एक हल्की-सी याद के लिए समय चुनें।", hl="Off hai. Sone se pehle ek halki si yaad ke liye time chunein.")
s("set_notifWindDownTime", "Wind-down time", "Row that opens the time picker for the wind-down reminder.", "నిద్రకు ముందు సమయం", "Wind-down time", hi="सोने से पहले के सुकून का समय", hl="Wind-down time")
s("set_notifWelcomeBack", "After a quiet while", "Switch: the 'welcome back' push.", "కొంత కాలం తర్వాత", "Konta kaalam tarvaata", hi="कुछ समय बाद", hl="Kuch samay baad")
s("set_notifWelcomeBackNote", "If you've been away a week or more, one gentle hello. Twice at most.", "Under the welcome-back switch. No guilt.", "మీరు వారం లేదా అంతకంటే ఎక్కువ దూరంగా ఉంటే, ఒక మృదువైన పలకరింపు. రెండు సార్లు మించదు.", "Meeru vaaram leda antakante ekkuva dooram ga unte, oka gentle hello. Rendu saarlu minchadu.", hi="एक हफ़्ते या उससे ज़्यादा की दूरी के बाद, एक हल्का-सा नमस्ते। ज़्यादा से ज़्यादा दो बार।", hl="Ek hafte ya usse zyada ki doori ke baad, ek halka sa hello. Zyada se zyada do baar.")
s("set_notifHabits", "Habit nudges", "Sub-heading: per-habit nudge times (opt-in).", "అలవాటు గుర్తులు", "Habit nudges", hi="आदतों की याद", hl="Habit nudges")
s("set_notifHabitsNote", "A small nudge at a time you pick, for any habit on Home. One a day at most.", "Under the habit nudges heading.", "Home లోని ఏ అలవాటుకైనా, మీరు ఎంచుకున్న సమయంలో ఒక చిన్న గుర్తు. రోజుకు ఒక్కటి మించదు.", "Home lo e habit ki aina, meeru select chesina time lo oka chinna nudge. Rojuki okkati minchadu.", hi="होम पर किसी भी आदत के लिए, आपके चुने समय पर एक छोटी-सी याद। दिन में ज़्यादा से ज़्यादा एक।", hl="Home par kisi bhi habit ke liye, aapke chune time par ek chhoti si yaad. Din mein zyada se zyada ek.")
s("set_notifHabitsNone", "Add a habit on Home to get a nudge for it.", "Habit nudges when there are no active habits.", "గుర్తు కోసం Home లో ఒక అలవాటు జోడించండి.", "Nudge kosam Home lo oka habit add cheyandi.", hi="याद पाने के लिए होम पर कोई आदत जोड़ें।", hl="Nudge ke liye Home par koi habit add karein.")
s("set_notifHabitOff", "Off", "Trailing value of a habit row without a nudge.", "ఆఫ్", "Off", hi="बंद", hl="Off")
s("set_notifHabitQuiet", "Inside your quiet hours, so it won't be sent.", "Under a habit nudge whose time is inside quiet hours.", "ఇది మీ నిశ్శబ్ద సమయంలో ఉంది, కాబట్టి రాదు.", "Idi mee quiet hours lo undi, kaabatti raadu.", hi="यह आपके शांत समय में है, इसलिए नहीं भेजा जाएगा।", hl="Ye aapke quiet hours mein hai, isliye nahi bheja jayega.")
s("set_notifHabitChange", "Change time", "Dialog action on a habit with a nudge.", "సమయం మార్చండి", "Time maarchandi", hi="समय बदलें", hl="Time badlein")
s("set_notifHabitTurnOff", "Turn off", "Dialog action: remove this habit's nudge.", "ఆఫ్ చేయండి", "Off cheyandi", hi="बंद करें", hl="Off karein")

# ---- Sounds › night wind-down (the wind-down reminder set from Sanctuary) ----
s("sounds_windDownRemind", "Remind me at {time}", "On the night wind-down card: turns on the opt-in wind-down reminder (asks for a time first). {time} e.g. '10:30 PM'.", "{time}కి గుర్తు చేయండి", "{time} ki gurthu cheyandi", STR("time"), hi="{time} पर याद दिलाएँ", hl="{time} par yaad dilayein")
s("sounds_windDownReminderOn", "A gentle reminder comes at {time}.", "On the wind-down card when the reminder is on.", "{time}కి ఒక మృదువైన గుర్తు వస్తుంది.", "{time} ki oka gentle reminder vastundi.", STR("time"), hi="{time} पर एक हल्की-सी याद आएगी।", hl="{time} par ek halki si yaad aayegi.")
s("sounds_windDownReminderOff", "Turn off", "Turns the wind-down reminder off from the card.", "ఆఫ్ చేయండి", "Off cheyandi", hi="बंद करें", hl="Off karein")
